def _grouped_measure(
    occupied: Sequence[int],
    side: int,
    pairs: Sequence[tuple[int, int, int, int]],
    facet_measure: Sequence[float],
    shared_by: float,
    spatial_dims: int,
) -> float:
    """
    Vector (Cauchy/Crofton) measure of the boundary inside one neighbourhood block.

    The facets separating foreground from background samples are accumulated as vectors oriented away from
    the samples of ``side``, grouped by the face-connected components of that side, and the norms of the
    resulting vectors are summed. Grouping the facets keeps the measure exact wherever the boundary is
    locally flat, while a boundary made of several separate pieces is measured piece by piece.
    """
    n_samples = len(occupied)
    root = list(range(n_samples))

    def _find(x: int) -> int:
        while root[x] != x:
            root[x] = root[root[x]]
            x = root[x]
        return x

    for i, j, _axis, _step in pairs:
        if occupied[i] == side and occupied[j] == side:
            root_i, root_j = _find(i), _find(j)
            if root_i != root_j:
                root[root_i] = root_j
    components: dict[int, np.ndarray] = {}
    for i, j, axis, step in pairs:
        if occupied[i] == occupied[j]:
            continue
        member = i if occupied[i] == side else j
        outwards = -step if member == i else step  # points away from the samples of `side`
        vector = components.setdefault(_find(member), np.zeros(spatial_dims, dtype=np.float64))
        vector[axis] += outwards * facet_measure[axis] / shared_by
    return float(sum(np.linalg.norm(vector) for vector in components.values()))


